// Single quote-state walker — the single source of truth for all three consumers.
function walkQuoteState(s: string, cb: (ch: string, index: number, q: string | null) => void): string | null {
  let q: string | null = null;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    cb(c, i, q);
    if (q === null) {
      if (c === "'" || c === '"') q = c;
    } else if (q === "'") {
      if (c === "'") { if (s[i + 1] === "'") i++; else q = null; }
    } else {
      if (c === '\\') i++;
      else if (c === '"') q = null;
    }
  }
  return q;
}

function stripComment(s: string): string {
  let cut = s.length;
  walkQuoteState(s, (ch, i, q) => { if (q === null && ch === '#') { cut = i; } });
  return s.slice(0, cut);
}

