const projectRootCache = new Map<string, string | null>();
const PROJECT_ROOT_MAX_DEPTH = 15;

export function resolveProjectRoot(file: string): string | null {
  let dir = path.dirname(pathResolve(file));
  for (let depth = 0; depth < PROJECT_ROOT_MAX_DEPTH; depth++) {
    const cached = projectRootCache.get(dir);
    if (cached !== undefined) return cached;
    const marker = path.join(dir, '.trident', 'knowledge-graph', 'shared.db');
    if (fs.existsSync(marker)) { projectRootCache.set(dir, dir); return dir; }
    const parent = path.dirname(dir);
    if (parent === dir) { projectRootCache.set(dir, null); return null; }
    dir = parent;
  }
  return null;
}

