export function bandAndAction(probability: number, policy: Policy): { band: "act" | "escalate" | "ignore"; action: "FIRE" | "ESCALATE" | "IGNORE" } {
  const band = probability >= policy.act ? "act" : probability >= policy.flag ? "escalate" : "ignore";
