/** Centralized IMMEDIATE transaction wrapper. */
private withImmediateTxn<T>(fn: () => T): T {
  this.db.exec("BEGIN IMMEDIATE;");
  try {
    const result = fn();
    this.db.exec("COMMIT;");
    return result;
  } catch (e) {
    try { this.db.exec("ROLLBACK;"); } catch { /* already rolled back */ }
    throw e;
  }
}

